mapper.select:
SELECT id, owner_id, slug, title, excerpt, cover_url, cover_asset_id, kind, status, version, like_count, comment_count, favorite_count, published_at, created_at, updated_at FROM creator_post WHERE owner_id = #{ownerId} AND status = 'PUBLISHED' AND published_at IS NOT NULL
AND (published_at < #{publishedAt} OR (published_at = #{publishedAt} AND id < #{postId}))
ORDER BY published_at DESC, id DESC LIMIT #{limit}

SELECT EXISTS (
    SELECT 1 FROM creator_post
    WHERE status = 'PUBLISHED' AND cover_asset_id = #{assetId}
    LIMIT 1
)

SELECT EXISTS (
    SELECT 1 FROM creator_post WHERE cover_asset_id = #{assetId} LIMIT 1
)
